rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /v0/{d} {
      allow read: if debug(null) != 0 || true;
    }
    match /v1/{d} {
      allow read: if debug(true) != 0 || true;
    }
    match /v2/{d} {
      allow read: if debug(2) != 0 || true;
    }
    match /v3/{d} {
      allow read: if debug(-9223372036854775807 - 1) != 0 || true;
    }
    match /v4/{d} {
      allow read: if debug(1.5) != 0 || true;
    }
    match /v5/{d} {
      allow read: if debug(100000000.0) != 0 || true;
    }
    match /v6/{d} {
      allow read: if debug(-0.0) != 0 || true;
    }
    match /v7/{d} {
      allow read: if debug(0.001) != 0 || true;
    }
    match /v8/{d} {
      allow read: if debug(0.0001) != 0 || true;
    }
    match /v9/{d} {
      allow read: if debug(float('NaN')) != 0 || true;
    }
    match /v10/{d} {
      allow read: if debug(float('Infinity')) != 0 || true;
    }
    match /v11/{d} {
      allow read: if debug(-float('Infinity')) != 0 || true;
    }
    match /v12/{d} {
      allow read: if debug('a"b\'c\nd\te') != 0 || true;
    }
    match /v13/{d} {
      allow read: if debug('é😀\u0001') != 0 || true;
    }
    match /v14/{d} {
      allow read: if debug('') != 0 || true;
    }
    match /v15/{d} {
      allow read: if debug(b'\x00\xffa') != 0 || true;
    }
    match /v16/{d} {
      allow read: if debug('é'.toUtf8()) != 0 || true;
    }
    match /v17/{d} {
