rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c/{d} {
      allow read: if d == 'x' && debug(d) == 'y' || debug(d.size()) == 1;
      allow read: if d == 'never';
    }
    match /t/{d} {
      allow read: if (d == 'x' ? debug(d + '1') : debug(d + '2')) != '' && (d == 'x' || d.size() == 9);
    }
  }
}

