rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function f(x) {
      let unused = debug('unused ' + x);
      let used = debug(x + '!');
      return used == 'a!';
    }
    match /c/{d} {
      allow read: if f(d) || f(d + d);
    }
  }
}

